B2BAdminFunderCompany = {
    init: async function(app, container, groupBucket) {
        app = app || session.app;
        container = container || $(".component[name=B2BAdminFunderCompany]");
        api.addToMetaCache([
            {
                "Name": "B2B",
                "Types": [
                    [meta[DTOs/FundingSummary]]
                ]
            }
        ]);
        if(!groupBucket) { return; }
        var companies = await model.getDatasource({
            endpoint: "B2B/Company",
            odataAppend: "?$filter=Buckets/any(b: b/Bucket/ParentId eq " + groupBucket + ")&$expand=Address,References,Buckets($expand=Bucket)",
            sort: { field: "Name", dir: "asc"}
        });

        var companyGrid = new GridWidget(container, companies);
        companyGrid.groupable = false;
        companyGrid.filterable = true;
        companyGrid.editable = true;
        companyGrid.detailTemplate = $("[name=companyDetails]", container).first().html();
        companyGrid.commands.push({ name: "save", icon: "k-i-save", text: "[resource_displayname[save]]" });
        companyGrid.commands.push({ name: "delete", icon: "k-i-delete", text: "[resource_displayname[delete]]"});
        companyGrid.dataBound = function (e) {
            $("[name=save]", companyGrid.gridElement).off("click").on("click", (e) => B2BAdminFunderCompany.save(e, companyGrid));
            $("[name=delete]", companyGrid.gridElement).off("click").on("click", (e) => B2BAdminFunderCompany.destroy(e, companyGrid, groupBucket));
        };
        companyGrid.detailExpand = async (e) => {
            if($(".k-tabstrip", $(e.detailRow)).length > 0) {
                return;
            }
            $("[name=tabs]", $(e.detailRow)).kendoTabStrip({ animation: { open: { effects: "fadeIn" } } });
            $("[name=toolbar]", $(e.detailRow)).kendoToolBar({items: [{ template: "<button name='fundingSummary'><span class='k-icon k-i-chart-area-stacked'></span>[resource_displayname[fundingsummary]]</button>" }]})
            var company = companyGrid.dataItem($(e.masterRow).closest("tr"));
            var matchedBucket = company.Buckets.filter(b => b.Bucket.ParentId === groupBucket)[0].Bucket;
            loadComponent($("[name=security]", $(e.detailRow)), "BucketedRoleManagement", (c) => c.init(app,$(".component[name=BucketedRoleManagement]", $(e.detailRow)), matchedBucket));
            loadComponent($("[name=details]", $(e.detailRow)), "CompanyDetails", (c) => c.init(app,$(".component[name=CompanyDetails]", $(e.detailRow)), company));
            loadComponent($("[name=fundingtypes]", $(e.detailRow)), "B2BAdminFundingTypes", (c) => c.init(app,$(".component[name=B2BAdminFundingTypes]", $(e.detailRow)), matchedBucket.Id));
            $("[name=fundingSummary]", $(e.detailRow)).on("click", (e) => B2BAdminFunderCompany.viewFundingSummary(e, matchedBucket.Id));
        };
        companyGrid.columns = [
            { field: "Name", title: "[resource_displayname[name]]" },
        ];
        await companyGrid.init();
    },

    viewFundingSummary: async function(e, funderBucketId) {
        e.preventDefault();
        var d = new Dialog({title: "[resource_displayname[fundingsummary]]", width: 1200, height: 600});
        d.init(async () => {
            var dataSource = await model.getDatasource({
                endpoint: "B2B/Bucket",
                odataAppend: "(" + funderBucketId + ")/FundingSummaryOverview()"
            });
            var g = new GridWidget(d.element, dataSource);
            g.groupable = false;
            g.columns = [
                {field: "Scheme", title: "[resource_displayname[scheme]]", width: 150},
                {field: "Description", title: "[resource_displayname[description]]", width: 200},
                {field: "Formula", title: "[resource_displayname[formula]]"},
                    { field: "IsSystematic", type: "boolean", title: "[resource_shortdisplayname[issystematic]]", width: 80, template: "<input type='checkbox' disabled class='k-checkbox k-checkbox-md k-rounded-md' name='isSystematic' #=(IsSystematic) ? 'checked' : ''# />"},
            ];
            g.init();
        });
    },

    save: async function (e, companyGrid) {
        e.preventDefault();
        var item = companyGrid.dataItem($(e.currentTarget).closest("tr"));
        await api.update("B2B/Company(" + item.Id + ")", item).then(() => {
            notification.success("[resource_displayname[saved]]");
            companyGrid.refresh();
        }).catch((err) => error(err));
    },

    destroy: async function (e, companyGrid, groupBucketId) {
        e.preventDefault();
        var item = companyGrid.dataItem($(e.currentTarget).closest("tr"));
        var matchedBucket = item.Buckets.filter(r => r.Bucket.ParentId === groupBucketId && r.Bucket.Key === "Funder")[0];
        await api.destroy("B2B/Bucket(" + matchedBucket.Bucket.Id + ")").then(() => {
            notification.success("[resource_displayname[deleted]]");
            companyGrid.refresh();
        }).catch((err) => error(err));
    }
}
